/**
 * 底部 tab 使用设计方提供的彩色 3D 图标：
 * - accent 保留原图质感（当前主题本身就是橙色）；
 * - gray 用灰度 + 暖灰着色，保留明暗层次，避免选中/未选中只是纯色遮罩。
 */
async function trimTransparent(buffer) {
  // 设计方给的 tab 图标四周有较多透明留白，直接缩到 81×81 会让图形只占 70%~85%。
  // 先裁掉透明边再缩放，视觉上图标更大，但 tabBar 本身仍是微信原生组件。
  try {
    return await sharp(buffer).ensureAlpha().trim({ threshold: 1 }).toBuffer()
  } catch {
    return buffer
  }
}

async function renderColorTabIcon(source, outName, size = 81) {
  const trimmed = await trimTransparent(await sharp(source).toBuffer())
  await sharp(trimmed)
    .resize(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png()
    .toFile(path.join(OUT, outName))
  console.log('  ✔', outName)
}

async function renderGrayTabIcon(source, outName, color = '#8B8179', size = 81) {
  const trimmed = await trimTransparent(await sharp(source).toBuffer())
  await sharp(trimmed)
    .resize(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .grayscale()
    .tint(color)
    .png()
    .toFile(path.join(OUT, outName))
  console.log('  ✔', outName)
}

/**
 * 把整张图标染成同一主题色，保留原始 alpha。
 *
 * 不用 sharp.tint：它对纯色 PNG 的处理会保留灰度明暗，得不到精确的 #EB5C20。
 * 这里直接改写 RGB、保留 alpha，白色镂空仍保持透明。
 */
/**
 * 角色肖像图标：工长 / 监理。
 *
 * 来源是设计方提供的 256×256 透明底 PNG（原始 .ico 已转存到 design-refs）。
 * 这些不是 SVG 图标，不能走 renderIcon；按 144px 输出，够 3x 真机在
 * 44dp 头像框里清晰显示，又不会把主包撑大。
 */
async function renderPortraitIcon(name, sourceName, size = 144) {
  const source = path.resolve(__dirname, '..', 'design-refs', sourceName)
  if (!fs.existsSync(source)) {
    console.warn(`  ! 缺少肖像源文件：${sourceName}，跳过 ${name}`)
    return
  }
  await sharp(source)
    .resize(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png({ compressionLevel: 9 })
    .toFile(path.join(OUT, name))
  console.log(`  ✔ ${name}`)
}

async function renderThemeTabIcon(source, outName, color = { r: 235, g: 92, b: 32 }, size = 81) {
  const trimmed = await trimTransparent(await sharp(source).toBuffer())
  const { data, info } = await sharp(trimmed)
    .resize(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true })

  for (let i = 0; i < data.length; i += info.channels) {
    data[i] = color.r
    data[i + 1] = color.g
    data[i + 2] = color.b
  }

  await sharp(data, {
    raw: { width: info.width, height: info.height, channels: info.channels },
  })
    .png({ compressionLevel: 9 })
    .toFile(path.join(OUT, outName))
  console.log('  ✔', outName)
}

